function loadPref(k,fallback){try{return JSON.parse(localStorage.getItem('aeris-'+k))??fallback;}catch{return fallback;}}
function savePref(k,v){try{localStorage.setItem('aeris-'+k,JSON.stringify(v));}catch{}}
