const map=new FlightMap($('.map-canvas'),selectFlight,selectAirport);
const selected=()=>currentFlights().find(f=>f.id===state.selected)||null;
function currentFlights(){if(state.mode==='live'&&state.replayTime!==null){return [...state.history.values()].map(h=>[...h].reverse().find(f=>f.positionTime<=state.replayTime)).filter(Boolean);}return state.flights;}
function visibleFlights(){return currentFlights().filter(f=>(f.altitude===null||f.altitude>=state.filter.min&&f.altitude<=state.filter.max)&&(state.filter.type==='all'||f.type===state.filter.type)&&(state.mode==='demo'||state.replayTime!==null||quality(f).age<=60||!f.positionTime));}
function displayFlight(f){return state.mode==='live'&&state.replayTime===null?predicted(f):f;}
function fmt(v,kind,digits=0){if(v===null||v===undefined||!Number.isFinite(v))return '—';let n=v;if(state.units==='metric'){if(kind==='alt')n*=FT;if(kind==='speed')n*=KT*3.6;if(kind==='vertical')n*=FT/60;}return new Intl.NumberFormat('en-SG',{maximumFractionDigits:digits,minimumFractionDigits:digits}).format(n);}
function unit(kind){return state.units==='metric'?({alt:'m',speed:'km/h',vertical:'m/s'}[kind]||kind):({alt:'ft',speed:'kt',vertical:'ft/min'}[kind]||kind);}
function phase(f){if(f.onGround)return 'On ground';if(f.verticalRate===null)return 'In flight';return f.verticalRate<-150?'Descending':f.verticalRate>150?'Climbing':'Cruising';}
function shortTime(t){return Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');}
function dataStatus(f){if(f.simulated)return 'Synthetic scenario · not a live flight';if(state.replayTime!==null)return 'Recorded in this session';const q=quality(f);return `${q.status} position · ${q.age<3600?Math.floor(q.age)+' s ago':'age unavailable'}`;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
function renderNav(){document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.action===state.nav));document.querySelectorAll('.rail>button').forEach(b=>b.classList.toggle('active',b.dataset.action===state.nav));$('.saved-count').textContent=state.saved.length?' · '+state.saved.length:'';}
function selectFlight(id){const f=currentFlights().find(f=>f.id===id);if(!f){toast('This flight is outside the current feed or replay window.');return;}state.selected=id;state.nav='explore';state.airport=null;$('#search').value='';closeSearch();renderNav();renderDetail();if(state.scene){scene?.select(displayFlight(f));if(terrain){terrain.destroy();terrain=null;$('.workspace').classList.remove('terrain-mode');scene.active=true;toast('Returned to the local 3D view for the selected aircraft.');}}if(innerWidth<=800)$('.workspace').classList.add('detail-open');updateMap();}
function selectAirport(id){state.airport=airports.find(a=>a.id===id);state.nav='airports';if(state.scene)closeScene();map.recenter(state.airport.lat,state.airport.lon);renderNav();renderDetail();if(innerWidth<=800)$('.workspace').classList.add('detail-open');closeSearch();}
function updateMap(){map.update(visibleFlights().map(displayFlight),state.selected,state.history);$('#flight-count').textContent=visibleFlights().length+' aircraft';const filter=state.filter;$('#filter-label').textContent=filter.min>0||filter.max<50000||filter.type!=='all'?'Filters · on':'Filters';}
function row(k,v){return `<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`;}
function metric(label,value,kind,key,ic,note=''){return `<button class="metric" data-metric="${key}"><span class="metric-label">${icon(ic)}${label}</span><span class="metric-value" data-value="${key}">${fmt(value,kind,kind==='vertical'&&state.units==='metric'?1:0)}<small>${unit(kind)}</small></span><span class="metric-note">${note}</span></button>`;}
function chart(f){let history=f.simulated?scenarioTrack(f.id):state.history.get(f.id)||[];history=history.filter(p=>p.altitude!==null);if(history.length<2)return '<div class="notice">The altitude profile appears after two position reports. Nothing is invented between missing reports.</div>';const max=Math.max(1000,...history.map(p=>p.altitude));let d=history.map((p,i)=>`${i?'L':'M'}${(i/(history.length-1)*280).toFixed(1)},${(64-p.altitude/max*55).toFixed(1)}`).join(' ');const x=f.simulated?state.demoTime/690*280:280;return `<div class="chart-heading">Altitude profile<span>${f.simulated?'SIMULATED':'THIS SESSION'} · ${unit('alt')}</span></div><svg class="alt-chart" viewBox="0 0 280 78" role="img" aria-label="${f.simulated?'Simulated':'Recorded'} altitude profile"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#8caa8d" stop-opacity=".25"/><stop offset="1" stop-color="#8caa8d" stop-opacity=".02"/></linearGradient></defs><path d="M0 20H280M0 43H280M0 65H280" stroke="#e7ece5" stroke-dasharray="3 4"/><path d="${d}L280 70H0Z" fill="url(#chartfill)"/><path d="${d}" fill="none" stroke="#729b7f" stroke-width="1.8"/><path d="M${x} 5V70" stroke="#d37d55" stroke-width="1" stroke-dasharray="2 3"/><circle cx="${x}" cy="${64-(f.altitude??0)/max*55}" r="3" fill="#d37d55" stroke="#fff" stroke-width="1.5"/></svg><div class="chart-axis"><span>${f.simulated?'Scenario start':'First report'}</span><span>${f.simulated?'Touchdown & rollout':'Most recent report'}</span></div>`;}
function flightItem(f,action='flight'){return `<button class="flight-list-item" data-${action}="${e(f.id)}"><span class="airline-monogram">${e(f.callsign.slice(0,2))}</span><span><strong>${e(f.callsign)}</strong><small>${e(f.airline||f.registration||f.source)}</small></span><span class="item-end"><strong>${e(f.type||'—')}</strong><small>${f.route?f.route.join(' → '):fmt(f.altitude,'alt')+' '+unit('alt')}</small></span>${icon('arrow')}</button>`;}
function renderDetail(){
 if(state.nav==='saved'){const available=currentFlights();const cards=state.saved.map(id=>available.find(f=>f.id===id)||state.savedMeta[id]).filter(Boolean);$('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption">YOUR COLLECTION<button class="iconbutton detail-close" style="display:none" data-action="toggle-detail" aria-label="Close details">${icon('close')}</button></div><div class="list-header"><h2>Saved flights.</h2><p>A small corner of the sky, just for you.<br>Saved on this device.</p></div>${cards.length?cards.map(f=>flightItem(f)).join(''):`<div class="empty">${icon('star')}<p>No flights saved yet.<br>Open a flight and tap the star.</p></div>`}${cards.length>=2?`<button class="secondary wide" data-action="compare" style="margin-top:24px">${icon('compare')} Compare saved flights</button>`:''}${cards.length?'<p class="fact-note">A saved flight may be outside the feed or no longer airborne. Stored metadata is a snapshot.</p><button class="secondary wide" data-action="clear-saved" style="margin-top:14px">Clear saved list</button>':''}</div>`;return;}
 if(state.nav==='airports'){renderAirports();return;}
 const f=selected();if(!f){$('#detail').innerHTML=`<div class="detail-inner"><h2>Your next discovery.</h2><div class="empty">${icon('plane')}<p>${state.mode==='live'?'The selected aircraft is no longer in this feed. Search or choose another aircraft.':'Choose an aircraft on the map, or use the search.'}</p></div><button class="secondary wide" data-action="nearby">Browse flights</button></div>`;return;}
 const type=aircraftTypes[f.type]||aircraftTypes.GENERIC;
 const route=f.route?`<div class="route-points"><div><div class="airport-code">${e(f.route[0])}</div><div class="route-place">${({MEL:'Melbourne',SIN:'Singapore',LHR:'London',KUL:'Kuala Lumpur',DXB:'Dubai',NRT:'Tokyo',HKG:'Hong Kong',CGK:'Jakarta',PEN:'Penang',BKK:'Bangkok'}[f.route[0]]||'Departure')}</div></div><div class="route-line">${icon('plane')}</div><div class="route-end"><div class="airport-code">${e(f.route[1])}</div><div class="route-place">${({SIN:'Singapore',MEL:'Melbourne',SYD:'Sydney',NRT:'Tokyo',CGK:'Jakarta',PEN:'Penang'}[f.route[1]]||'Destination')}</div></div></div>`:'<div class="route-points"><div><div class="airport-code" style="font-size:19px">Route unavailable</div><div class="route-place">ADS-B positions do not establish a scheduled route.</div></div></div>';
 const tabs=['overview','aircraft','telemetry'];
 let content='';if(state.tab==='overview'){content=`<div class="metric-grid">${metric('Barometric altitude',f.altitude,'alt','altitude','altitude',f.simulated?'Simulated':'Pressure referenced')}${metric('Ground speed',f.groundSpeed,'speed','groundSpeed','speed','Over the ground')}${metric('Vertical speed',f.verticalRate,'vertical','verticalRate','vertical',f.verticalRate<0?'Descending':f.verticalRate>0?'Climbing':'Level / unavailable')}${metric('Ground track',f.track,'°','track','heading','Direction of travel')}</div><div id="altitude-chart">${chart(f)}</div>`;}
 else if(state.tab==='aircraft'){content=`<h3>${e(type.name)}</h3><p class="fact-note" style="margin-top:5px">${e(type.family)}</p><dl class="fact-list">${row('Registration',f.registration||'Not reported')}${row('ICAO type',f.type||'Not reported')}${row('Length',type.length+' m')}${row('Wingspan',type.span+' m')}${row('Height',type.height+' m')}${row('Engines',type.engines)}${row('Serial number / age','Not connected')}</dl><p class="geometry-note">${type===aircraftTypes.GENERIC?'Type is unknown; the generic model is illustrative.':'Reference dimensions; original parametric mesh. Exact airframe, engine variant and livery are not verified.'}</p>${type.source?`<a class="small-link" href="${type.source}" target="_blank" rel="noreferrer">Aircraft manufacturer reference ↗</a>`:''}`;}
 else{const age=quality(f);content=`<div class="metric-grid">${metric('Indicated airspeed',f.indicatedAirspeed,'speed','indicatedAirspeed','speed','Only if reported')}${metric('True airspeed',f.trueAirspeed,'speed','trueAirspeed','speed','Only if reported')}</div><dl class="fact-list">${row('Mach',f.mach===null?'Not reported':f.mach.toFixed(3))}${row('Geometric altitude',f.geometricAltitude===null?'Not reported':fmt(f.geometricAltitude,'alt')+' '+unit('alt'))}${row('True heading',f.trueHeading===null?'Not reported':fmt(f.trueHeading,'°')+'°')}${row('Roll angle',f.roll===null?'Not reported':f.roll.toFixed(1)+'°')}${row('Squawk',f.squawk||'Not reported')}${row('Position',f.lat.toFixed(5)+'°, '+f.lon.toFixed(5)+'°')}${row('ICAO 24-bit address',f.simulated?'Synthetic aircraft':f.id)}${row('Source',f.source)}${row('Position age',f.simulated?'Simulated':age.age<3600?Math.floor(age.age)+' seconds':'Unknown')}</dl><button class="secondary wide" style="margin-top:18px" data-action="export">${icon('download')} Export session track</button>`;}
 $('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption"><span>FLIGHT EXPLORER</span><span class="tag">${f.simulated?'SIMULATED':state.replayTime!==null?'REPLAY':e(quality(f).status.toUpperCase())}</span><button class="iconbutton detail-close" style="display:none" data-action="toggle-detail" aria-label="Close details">${icon('close')}</button></div><div class="airline-row"><span class="airline-monogram">${e(f.callsign.slice(0,2))}</span><div class="flight-heading"><h2>${e(f.callsign)}</h2><p>${e(f.airline||f.registration||'Unidentified operator')}</p></div><button class="iconbutton ${state.saved.includes(f.id)?'saved-star':''}" data-action="save-flight" aria-label="${state.saved.includes(f.id)?'Unsave':'Save'} ${e(f.callsign)}" title="Save flight" aria-pressed="${state.saved.includes(f.id)}">${icon('star')}</button></div><div class="route-card">${route}<div class="route-status"><span class="phase"><span class="dot"></span><span id="flight-phase">${phase(f)}</span></span><span>${f.simulated?'Illustrative flight':'Route not inferred'}</span></div></div><button class="view-card" data-action="3d" aria-label="Explore ${e(f.callsign)} in 3D"><span class="three-label">A NEW PERSPECTIVE</span>${planeSVG}<span class="view-label"><strong>Step into the flight.</strong><small>Orbit, follow, and explore in 3D</small></span><span class="view-arrow">${icon('arrow')}</span></button><div class="detail-tabs" role="tablist" aria-label="Flight information">${tabs.map(t=>`<button role="tab" aria-selected="${state.tab===t}" class="${state.tab===t?'active':''}" data-tab="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div role="tabpanel">${content}</div><div class="data-source">${icon('signal')}<span><strong>${f.simulated?'Made for exploring. Labelled honestly.':'Know what you are seeing.'}</strong><span id="detail-data-status">${dataStatus(f)}</span><br>${f.simulated?'No real flight status or airline livery is implied.':'Attitude and between-report motion are reconstructed.'}</span></div></div>`;
 $('#mobile-flight-name').textContent=f.callsign;$('#scene-callsign').textContent=f.callsign+' · '+(f.type||'Aircraft');$('#scene-source').textContent=f.simulated?'SIMULATED FLIGHT':state.replayTime!==null?'SESSION REPLAY':quality(f).status.toUpperCase()+' · ADS-B';
}
function renderAirports(){const a=state.airport;if(!a){$('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption">ON THE GROUND<button class="iconbutton detail-close" style="display:none" data-action="toggle-detail" aria-label="Close details">${icon('close')}</button></div><div class="list-header"><h2>Places of possibility.</h2><p>Explore the airports around Singapore.<br>Runway reference data, all in one place.</p></div><div class="airport-list">${airports.map(a=>`<button class="airport-card" data-airport="${a.id}"><span class="airport-code">${a.id}</span><span><strong>${a.name}</strong><small>${a.icao} · ${a.city}</small></span>${icon('arrow')}</button>`).join('')}</div><div class="notice">Reference information only. Active runways, NOTAMs, gates and operating conditions require separate current airport data.</div></div>`;return;}
 $('#detail').innerHTML=`<div class="detail-inner"><div class="detail-caption"><button data-action="airports">${icon('back')} ALL AIRPORTS</button><span>${a.icao}</span></div><div class="list-header"><h2>${a.name}</h2><p>${a.city} · ${a.id}</p></div><div class="airport-plan"><svg viewBox="0 0 300 135" aria-label="Schematic runway layout"><g transform="translate(150 67) rotate(23)">${a.runways.map((r,i)=>`<rect x="${(i-(a.runways.length-1)/2)*60-3}" y="-70" width="6" height="140" rx="2" fill="#70897e"/><path d="M${(i-(a.runways.length-1)/2)*60} -65v130" stroke="#dbe5d6" stroke-dasharray="5 5"/>`).join('')}<rect x="-15" y="-20" width="30" height="40" rx="3" fill="#c4d3bf"/></g></svg><span>SCHEMATIC · NOT TO SCALE</span></div><dl class="fact-list">${row('ICAO / IATA',a.icao+' / '+a.id)}${row('Coordinates',a.lat.toFixed(4)+'° N · '+a.lon.toFixed(4)+'° E')}${row('Field elevation',fmt(a.elevation,'alt')+' '+unit('alt'))}${row('Local time',new Date().toLocaleTimeString('en-GB',{timeZone:a.tz,hour:'2-digit',minute:'2-digit'})+' · '+a.tz)}</dl><div class="section-sub">RUNWAY REFERENCE</div><dl class="fact-list">${a.runways.map(r=>row(r[0],r[1].toLocaleString()+' × '+r[2]+' m')).join('')}</dl><div class="notice">Runway dimensions are reference data, not a statement of operational availability. Live weather, schedules and gate data are not connected.</div><a class="secondary wide" style="display:block;text-align:center;text-decoration:none" href="${a.website}" target="_blank" rel="noreferrer">Official airport website ↗</a></div>`;
}
function renderClock(){const now=new Date();$('#clock').textContent=now.toLocaleTimeString('en-GB',{timeZone:'Asia/Singapore',hour:'2-digit',minute:'2-digit',second:'2-digit'})+' SGT';$('#clock').dateTime=now.toISOString();}
function renderPlayback(){const demo=state.mode==='demo';$('.play').innerHTML=icon(state.playing?'pause':'play');$('.play').setAttribute('aria-label',state.playing?'Pause replay':'Play replay');$('.speed').textContent=state.rate+'×';$('#playback-label').textContent=demo?'DEMO REPLAY':state.replayTime===null?'LIVE POSITIONS':'SESSION REPLAY';$('#playback-phase').textContent=demo?(state.selected==='demo-tr18'?'Takeoff → climb':state.selected==='demo-sq228'?'Approach → landing':'Illustrative flight'):state.lastFetch?'Reports recorded in this tab':'Awaiting reports';$('#return-live').textContent=demo?'RESET':'GO LIVE';
 const slider=$('#timeline');if(demo){slider.min=0;slider.max=DEMO_DURATION;slider.disabled=false;slider.value=state.demoTime;$('#time-readout').textContent=shortTime(state.demoTime)+' / '+shortTime(DEMO_DURATION);}else{const h=state.history.get(state.selected)||[];const start=h[0]?.positionTime||0,end=h.at(-1)?.positionTime||start;slider.min=start;slider.max=end||1;slider.value=state.replayTime??end;slider.disabled=h.length<2;$('.play').disabled=h.length<2;$('#time-readout').textContent=h.length>1?shortTime((state.replayTime??end)-start):'Recording…';}if(demo)$('.play').disabled=false;
 $('#source-text').textContent=state.mode==='demo'?(state.error?'DEMO · FEED ERROR':'DEMO TRAFFIC'):state.error?'FEED DISCONNECTED':state.replayTime!==null?'SESSION REPLAY':'LIVE FEED';$('#source-pill').classList.toggle('live',state.mode==='live'&&!state.error&&state.replayTime===null);$('#source-pill').classList.toggle('error',Boolean(state.error));$('#feed-error').textContent=state.error;
}
function refresh(){renderNav();renderDetail();renderPlayback();updateMap();}
function closeSearch(){$('#search-results').classList.remove('open');$('#search').setAttribute('aria-expanded','false');}
function search(){const q=$('#search').value.trim().toLowerCase();if(!q){closeSearch();return;}const found=currentFlights().filter(f=>[f.callsign,f.registration,f.type,f.airline,...f.route||[]].some(v=>String(v||'').toLowerCase().includes(q)));const ap=airports.filter(a=>[a.id,a.icao,a.name,a.city].some(v=>v.toLowerCase().includes(q)));$('#search-results').innerHTML=found.slice(0,7).map(f=>`<button class="result" data-flight="${e(f.id)}">${icon('plane')}<span><b>${e(f.callsign)}</b><small>${e(f.airline||f.registration||'Aircraft')}</small></span><span class="result-right">${e(f.type||'—')}</span></button>`).join('')+ap.map(a=>`<button class="result" data-airport="${a.id}">${icon('airport')}<span><b>${a.id}</b><small>${a.name}</small></span><span class="result-right">${a.icao}</span></button>`).join('')+(!found.length&&!ap.length?'<div class="empty">No matches in this feed.<br>Try an airport code or aircraft type.</div>':'');$('#search-results').classList.add('open');$('#search').setAttribute('aria-expanded','true');}
function openDialog(title,body){const d=$('#dialog');dialogFocus=document.activeElement;d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${e(title)}</h2><button class="iconbutton" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal();}
function closeDialog(){if($('#dialog').open)$('#dialog').close();dialogFocus?.focus?.();}
$('#dialog').addEventListener('click',ev=>{if(ev.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog();}});
function showFilters(){openDialog('Find your kind of flight.',`<p>Filter the aircraft in this region. Aircraft without an altitude report remain visible.</p><label class="form-field">Aircraft type<select id="filter-type"><option value="all">All aircraft</option>${[...new Set(currentFlights().map(f=>f.type).filter(Boolean))].sort().map(t=>`<option ${state.filter.type===t?'selected':''}>${e(t)}</option>`).join('')}</select></label><div class="form-row"><label class="form-field">Minimum altitude (ft)<input id="filter-min" type="number" min="0" max="60000" step="1000" value="${state.filter.min}"></label><label class="form-field">Maximum altitude (ft)<input id="filter-max" type="number" min="0" max="60000" step="1000" value="${state.filter.max}"></label></div><div class="form-error" id="filter-error"></div><div class="button-row"><button class="primary" data-action="apply-filters">Apply filters</button><button class="secondary" data-action="reset-filters">Reset</button></div>`);}
function showLayers(){openDialog('A map with room to breathe.',`<p>Keep the details you care about. Map boundaries are generalised reference geography.</p>${[['labels','Flight and place labels','Callsigns, cities and sea labels'],['trails','Selected flight trail','Observed positions, or the labelled demo path'],['airports','Airport markers','Open an airport to inspect its runways'],['dark','Night map','A lower-brightness map palette']].map(([key,label,note])=>`<label class="switch-row"><span>${label}<small>${note}</small></span><input type="checkbox" data-layer="${key}" ${map[key]?'checked':''}></label>`).join('')}<div class="button-row"><button class="primary" data-action="close-dialog">Done</button></div>`);}
function showSettings(){openDialog('Make the sky your own.',`<label class="form-field">Units<select id="units"><option value="aviation" ${state.units==='aviation'?'selected':''}>Aviation · feet, knots, ft/min</option><option value="metric" ${state.units==='metric'?'selected':''}>Metric · metres, km/h, m/s</option></select></label><label class="form-field">3D rendering<select id="render-quality"><option value="high">High detail</option><option value="low" ${state.quality==='low'?'selected':''}>Battery friendly</option></select><small>Battery mode lowers pixel resolution and disables shadows.</small></label><div class="button-row"><button class="secondary" data-action="connect">Data connection</button><button class="secondary" data-action="terrain">Real-world terrain</button></div><p class="fact-note">Preferences and saved flights stay on this device. The offline demo needs no account. System reduced-motion preferences are respected.</p><div class="button-row"><button class="primary wide" data-action="save-settings">Save preferences</button></div>`);}
function showConnect(){openDialog('Connect to the real sky.',`<p>The demo is always available. For live traffic, connect to an authorised ADS-B source. Coverage and optional telemetry depend on its receivers.</p><div class="source-buttons"><button class="${state.mode==='demo'?'active':''}" data-action="use-demo">Demo scenario</button><button class="${state.mode==='live'?'active':''}" data-action="connect-preset">ADSB.lol</button></div><label class="form-field">ADS-B v2 endpoint<input id="endpoint" type="url" value="${e(state.endpoint||defaultEndpoint())}" spellcheck="false"><small>Expected response: an object with an ac array. A private receiver must allow browser access. Do not paste credentials here.</small></label><div class="notice">ADSB.lol data is ODbL. It is a best-effort service; availability, keys and limits can change. Contact the provider before production use. This app polls at most every 15 seconds and pauses in a hidden tab.</div><p id="connection-status" class="form-status">${state.mode==='live'?'Connected to '+e(state.endpoint):'You are viewing a synthetic scenario.'}</p><div class="form-error" id="connection-error"></div><div class="button-row"><button class="primary wide" data-action="connect-feed">${icon('signal')} Connect live feed</button></div><a href="https://api.adsb.lol/docs" target="_blank" rel="noreferrer" class="small-link">Provider documentation ↗</a>`);}
function defaultEndpoint(){return defaultFeedEndpoint(location);}
async function connectFeed(){const attemptGeneration=generation;const input=$('#endpoint'),button=$('[data-action="connect-feed"]');let url;try{url=parseEndpoint(input.value.trim());}catch(err){$('#connection-error').textContent=err.message;return;}button.disabled=true;button.textContent='Connecting…';$('#connection-error').textContent='';try{const flights=await fetchFeed(url);if(attemptGeneration!==generation)return;stopPolling();state.mode='live';state.endpoint=url;state.flights=flights;state.history.clear();record(flights);state.selected=flights[0]?.id||null;state.connected=true;state.error='';state.playing=false;state.replayTime=null;state.lastFetch=Date.now()/1000;state.nav='explore';state.airport=null;if(state.scene)closeScene();closeDialog();refresh();schedulePoll();toast(flights.length?`Connected. ${flights.length} positioned aircraft received.`:'Connected. No positioned aircraft reported in this region.');}catch(err){if(attemptGeneration!==generation)return;if($('#connection-error'))$('#connection-error').textContent=err.message;state.error='Live connection failed. Demo remains active.';if(state.mode==='live')state.error='Live connection failed. Existing reports are retained with their original timestamps.';renderPlayback();}finally{if(button.isConnected){button.disabled=false;button.innerHTML=icon('signal')+' Connect live feed';}}}
async function fetchFeed(url){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),10000);request=controller;try{const r=await fetch(url,{signal:controller.signal,cache:'no-store',credentials:'omit',headers:{Accept:'application/json'}});if(!r.ok)throw new Error(r.status===429?'The provider is rate limiting requests. Retry later.':`The feed returned HTTP ${r.status}. Check provider access or use your own receiver.`);const text=await r.text();if(text.length>5_000_000)throw new Error('The feed is too large. Request a smaller geographic area.');return normalizeADSB(JSON.parse(text));}catch(err){if(err.name==='AbortError')throw new Error('The request timed out or was cancelled.');if(err instanceof TypeError)throw new Error('Cannot reach this feed. Check network access, CORS and the endpoint.');throw err;}finally{clearTimeout(timeout);if(request===controller)request=null;}}
function record(flights){for(const f of flights){if(!f.positionTime)continue;const h=state.history.get(f.id)||[];if(!h.length||f.positionTime>h.at(-1).positionTime){h.push({...f});while(h.length>121)h.shift();state.history.set(f.id,h);}}const cutoff=Date.now()/1000-1800;for(const [id,h] of state.history){while(h.length&&h[0].positionTime<cutoff)h.shift();if(!h.length)state.history.delete(id);}if(state.history.size>1000){const order=[...state.history].sort((a,b)=>a[1].at(-1).positionTime-b[1].at(-1).positionTime);for(const [id] of order.slice(0,order.length-1000))state.history.delete(id);}}
function stopPolling(){generation++;clearTimeout(pollTimer);request?.abort();request=null;}
function schedulePoll(delay=15000){clearTimeout(pollTimer);pollTimer=setTimeout(poll,delay);}
async function poll(){if(state.mode!=='live')return;if(document.hidden){schedulePoll();return;}const g=generation;try{const flights=await fetchFeed(state.endpoint);if(g!==generation||state.mode!=='live')return;state.flights=flights;record(flights);state.lastFetch=Date.now()/1000;state.connected=true;state.error='';refresh();schedulePoll();}catch(err){if(g!==generation)return;state.connected=false;state.error='Feed disconnected · last reports kept. Retrying in 60 seconds.';renderPlayback();schedulePoll(60000);}}
function useDemo(){stopPolling();state.mode='demo';state.demoTime=410;state.flights=demoFlights(410);state.selected='demo-sq228';state.history.clear();state.replayTime=null;state.playing=false;state.error='';state.nav='explore';state.airport=null;state.connected=false;if(state.scene)closeScene();closeDialog();map.recenter();refresh();}
async function openScene(camera='orbit'){const f=selected();if(!f){toast('Choose an aircraft first.');return false;}if(camera!=='globe'&&!f.simulated&&f.altitude===null&&f.geometricAltitude===null){toast('No altitude is reported. Open the globe to see this position.');return false;}if(!scene){try{scene=new FlightScene($('#scene'),toast);}catch{return;}}state.scene=true;state.camera=camera;$('.workspace').classList.add('scene-mode');$('.workspace').classList.remove('detail-open');scene.active=true;scene.resize();scene.select(displayFlight(f));scene.setCamera(camera);setCameraUI(camera);renderDetail();return true;}
function closeScene(){state.scene=false;$('#map-credit').textContent='Map: Natural Earth · generalised geography';$('.workspace').classList.remove('scene-mode','terrain-mode');if(scene)scene.active=false;if(terrain){terrain.destroy();terrain=null;}updateMap();}
function setCameraUI(mode){state.camera=mode;$('#scene-fidelity').textContent=mode==='globe'?'Geographic globe · demo route height exaggerated':'Parametric aircraft · schematic ground';document.querySelectorAll('[data-camera]').forEach(b=>{b.classList.toggle('active',b.dataset.camera===mode);b.setAttribute('aria-pressed',String(b.dataset.camera===mode));});$('#scene-help').textContent=mode==='free'?'Drag to look · W A S D to move · Q / E down / up · Shift for speed':mode==='orbit'?'Drag to orbit · scroll to move closer':mode==='globe'?'Drag to orbit Earth · scroll to zoom':'Reconstructed orientation · not an onboard camera';}
function terrainDialog(){openDialog('Geography, with real depth.',`<p>The built-in 3D view uses real coastlines with schematic terrain and airport structures. Connect Cesium ion for elevation, satellite imagery and optional Google Photorealistic 3D Tiles.</p><label class="form-field">Your public Cesium ion access token<input id="terrain-token" type="password" autocomplete="off" placeholder="Paste a browser-scoped token"><small>Use a least-privilege, domain-restricted public token. It stays in memory for this session and is sent only to the provider.</small></label><div class="notice">Provider usage may be metered. Enable World Terrain and imagery in your own account. Photorealistic 3D Tiles load only if your account permits them; otherwise the viewer uses terrain and imagery. Coverage and observation age vary.</div><div class="form-error" id="terrain-error"></div><button class="primary wide" data-action="load-terrain">Connect terrain</button><a class="small-link" href="https://cesium.com/learn/cesiumjs-learn/cesiumjs-flight-tracker/" target="_blank" rel="noreferrer">Terrain provider setup ↗</a>`);}
async function loadTerrain(){const f=selected();if(!f){$('#terrain-error').textContent='Select a flight before connecting terrain.';return;}const token=$('#terrain-token').value.trim();if(!token){$('#terrain-error').textContent='Enter your own public provider token.';return;}const btn=$('[data-action="load-terrain"]');btn.disabled=true;btn.textContent='Loading terrain…';try{if(!await openScene('orbit'))throw new Error('A usable 3D position is required.');$('.workspace').classList.add('terrain-mode');terrain?.destroy();terrain=await startTerrain($('#terrain'),token,f);terrainToken=token;scene.active=false;$('#scene-fidelity').textContent=terrain.photoreal?'Provider-backed photorealistic 3D tiles':'Provider-backed terrain & imagery';$('#map-credit').textContent='Terrain & imagery provider attribution appears in the viewer';closeDialog();toast(terrain.photoreal?'Photorealistic terrain connected.':'Terrain connected. Photorealistic tiles are unavailable on this account.');}catch(err){$('.workspace').classList.remove('terrain-mode');if(scene)scene.active=true;if($('#terrain-error'))$('#terrain-error').textContent='Could not connect terrain. '+err.message;}finally{if(btn.isConnected){btn.disabled=false;btn.textContent='Connect terrain';}}}
const definitions={
 altitude:['Barometric altitude','Altitude calculated from atmospheric pressure, usually referenced to standard pressure. It is not necessarily height above terrain. Geometric altitude is a separate satellite-position measurement; a production terrain renderer also needs consistent vertical datums.'],
 groundSpeed:['Ground speed','How fast the aircraft travels relative to the ground. Wind makes it different from airspeed. Knots are nautical miles per hour; one knot is 1.852 km/h.'],
 verticalRate:['Vertical speed','The reported rate of climb or descent. A negative value means descent. Source data may be barometric or geometric, depending on what was received.'],
 track:['Ground track','The direction the aircraft moves across the ground, clockwise from true north. Wind can make this different from the heading of the nose.'],
 indicatedAirspeed:['Indicated airspeed','A cockpit airspeed reading based on pitot/static pressure. It is shown only when an extended surveillance report supplies it. It cannot be recovered reliably from ground speed alone.'],
 trueAirspeed:['True airspeed','Speed relative to the surrounding airmass. It differs from both indicated airspeed and ground speed. Missing reports are shown as unavailable.']
};
function showSources(){openDialog('A clearer picture. Including the gaps.',`<p>Aeris is an original prototype. It does not use Flightradar24 private endpoints, paid content, code, aircraft assets or branding.</p><div class="notice"><strong>Demo mode</strong><br>All aircraft positions, routes and telemetry in the scenario are synthetic. The scenario includes an illustrative approach, touchdown and rollout. Select SQ228 for landing or TR18 for takeoff. It is not a reconstruction of an actual flight.</div><p><strong>3D accuracy</strong><br>Coastlines are generalised. Default ground elevation and airport buildings are schematic. Parametric aircraft match reference dimensions approximately. Attitude, pitch and between-report motion are estimates, not measured aircraft dynamics. Default lighting and clouds are illustrative. This is not navigation or flight-simulation software.</p><p><strong>Live reports</strong><br>Each position keeps its timestamp. Extrapolation stops after 10 seconds, positions are marked stale after 15 seconds, and disappear from the active map after 60 seconds. Session tracks retain only up to 121 reports per aircraft. No scheduled route, airspeed, gear state or age is invented.</p><ul class="link-list"><li><a href="https://api.adsb.lol/docs" target="_blank" rel="noreferrer">ADSB.lol · optional live feed · ODbL</a></li><li><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noreferrer">Natural Earth · public-domain generalised geography</a></li><li><a href="https://github.com/markmarkoh/datamaps" target="_blank" rel="noreferrer">DataMaps · Natural Earth-derived regional boundaries</a></li><li><a href="https://ourairports.com/data/" target="_blank" rel="noreferrer">OurAirports · public-domain airport reference data</a></li><li><a href="https://threejs.org/" target="_blank" rel="noreferrer">Three.js · MIT · original procedural aircraft</a></li><li><a href="https://cesium.com/" target="_blank" rel="noreferrer">Cesium · optional terrain and imagery</a></li></ul>`);}
function showHelp(){openDialog('A little closer to the sky.',`<p>Select any aircraft to explore its details. The 3D viewer lets you move around the aircraft, follow behind it, or look ahead from a reconstructed cockpit position.</p><div class="kbd-row"><span>Search flights & airports</span><kbd>/</kbd></div><div class="kbd-row"><span>Pan map / orbit aircraft</span><kbd>Drag</kbd></div><div class="kbd-row"><span>Zoom</span><kbd>Scroll · + / −</kbd></div><div class="kbd-row"><span>Free camera movement</span><kbd>W A S D · Q E</kbd></div><div class="kbd-row"><span>Play / pause replay</span><kbd>Space</kbd></div><div class="kbd-row"><span>Return to map</span><kbd>Esc</kbd></div><div class="notice">For free camera, click the 3D view first. Touch: one finger orbits; two fingers zoom and pan. On a phone, tap the flight button to open details.</div><button class="secondary wide" data-action="connect">Choose a data source</button>`);}
function compare(){const flights=state.saved.map(id=>currentFlights().find(f=>f.id===id)).filter(Boolean).slice(0,4);if(flights.length<2){toast('At least two saved flights must be present in the current feed.');return;}openDialog('Side by side.',`<p>Comparing the first ${flights.length} saved flights present in this feed. Values retain their original reporting basis.</p><table class="comparison"><tr><th>Flight</th>${flights.map(f=>`<th>${e(f.callsign)}</th>`).join('')}</tr>${[['Aircraft',f=>f.type||'—'],['Altitude',f=>fmt(f.altitude,'alt')+' '+unit('alt')],['Ground speed',f=>fmt(f.groundSpeed,'speed')+' '+unit('speed')],['Vertical speed',f=>fmt(f.verticalRate,'vertical')+' '+unit('vertical')],['Data',f=>f.simulated?'Simulated':quality(f).status]].map(([label,fn])=>`<tr><td>${label}</td>${flights.map(f=>`<td>${e(fn(f))}</td>`).join('')}</tr>`).join('')}</table>`);}
function exportTrack(){const f=selected();if(!f)return;let points=f.simulated?scenarioTrack(f.id):state.history.get(f.id)||[];if(!points.length){toast('No track reports recorded for this aircraft yet.');return;}const quote=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'" ).replaceAll('"','""')+'"';const head=['callsign','data_mode','timestamp_utc','scenario_seconds','latitude','longitude','barometric_altitude_ft','geometric_altitude_ft','ground_speed_kt','vertical_rate_ft_min','track_deg'];const csv=[head.join(','),...points.map(p=>[p.callsign,p.simulated?'synthetic':'observed',p.simulated?'':new Date(p.positionTime*1000).toISOString(),p.scenarioSeconds??'',p.lat,p.lon,p.altitude,p.geometricAltitude,p.groundSpeed,p.verticalRate,p.track].map(quote).join(','))].join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aeris-'+f.callsign.replace(/[^a-z0-9]/gi,'_')+'-'+(f.simulated?'synthetic':'session')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Track exported with source and units.');}
function togglePlay(){if(state.mode==='live'&&state.replayTime===null){const h=state.history.get(state.selected)||[];if(h.length<2){toast('Wait for a second report to start session replay.');return;}state.replayTime=h[0].positionTime;}if(state.mode==='demo'&&state.demoTime>=DEMO_DURATION)state.demoTime=0;state.playing=!state.playing;renderPlayback();}
const actions={
 explore(){state.nav='explore';state.airport=null;renderNav();renderDetail();},saved(){state.nav='saved';renderNav();renderDetail();if(innerWidth<=800)$('.workspace').classList.add('detail-open');},airports(){state.nav='airports';state.airport=null;renderNav();renderDetail();if(innerWidth<=800)$('.workspace').classList.add('detail-open');},
 nearby(){openDialog('In this part of the sky.',`<p>${visibleFlights().length} aircraft in the current feed and filters. ${state.mode==='demo'?'This is a synthetic scenario.':''}</p>${visibleFlights().length?visibleFlights().map(f=>flightItem(f)).join(''):'<div class="empty">No matching aircraft. Change filters or wait for coverage.</div>'}`);},
 'zoom-in':()=>map.zoom(1.3),'zoom-out':()=>map.zoom(1/1.3),north:()=>map.recenter(),recenter(){const f=selected();if(f)map.recenter(f.lat,f.lon);else map.recenter();},filters:showFilters,layers:showLayers,settings:showSettings,connect:showConnect,sources:showSources,help:showHelp,terrain:terrainDialog,'load-terrain':loadTerrain,
 'close-dialog':closeDialog,'toggle-detail':()=>$('.workspace').classList.toggle('detail-open'),'3d':()=>openScene(),globe:()=>openScene('globe'),map:closeScene,'reset-camera'(){scene?.setCamera(state.camera);},
 light(){state.light=state.light==='day'?'dusk':state.light==='dusk'?'night':'day';scene?.setLight(state.light);toast(state.light[0].toUpperCase()+state.light.slice(1)+' lighting · illustrative');},
 play:togglePlay,rate(){state.rate=state.rate===1?4:state.rate===4?16:1;renderPlayback();},'return-live'(){state.playing=false;if(state.mode==='demo'){state.demoTime=0;state.flights=demoFlights(0);}else state.replayTime=null;refresh();},
 'save-flight'(){const f=selected();if(!f)return;if(state.saved.includes(f.id)){state.saved=state.saved.filter(id=>id!==f.id);delete state.savedMeta[f.id];toast('Removed from saved flights.');}else{state.saved.push(f.id);state.savedMeta[f.id]=f;toast(f.callsign+' saved on this device.');}savePref('saved',state.saved);savePref('savedMeta',state.savedMeta);renderNav();renderDetail();},
 'clear-saved'(){state.saved=[];state.savedMeta={};savePref('saved',[]);savePref('savedMeta',{});renderNav();renderDetail();toast('Saved list cleared.');},compare,export:exportTrack,
 'apply-filters'(){const min=Number($('#filter-min').value),max=Number($('#filter-max').value);if(!Number.isFinite(min)||!Number.isFinite(max)||min<0||max>60000||min>max){$('#filter-error').textContent='Use altitudes from 0 to 60,000 ft, with minimum no greater than maximum.';return;}state.filter={min,max,type:$('#filter-type').value};updateMap();closeDialog();toast(visibleFlights().length+' aircraft match your filters.');},
 'reset-filters'(){state.filter={min:0,max:50000,type:'all'};updateMap();closeDialog();},
 'save-settings'(){state.units=$('#units').value;state.quality=$('#render-quality').value;savePref('units',state.units);scene?.setQuality(state.quality);closeDialog();refresh();toast('Preferences updated.');},'use-demo':useDemo,'connect-feed':connectFeed,'connect-preset'(){if($('#endpoint'))$('#endpoint').value=defaultEndpoint();},
};
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!ev.target.closest('.search-area'))closeSearch();if(!b)return;if(b.dataset.action){actions[b.dataset.action]?.();}else if(b.dataset.flight){closeDialog();selectFlight(b.dataset.flight);}else if(b.dataset.airport){closeDialog();selectAirport(b.dataset.airport);}else if(b.dataset.tab){state.tab=b.dataset.tab;renderDetail();}else if(b.dataset.camera){scene?.setCamera(b.dataset.camera);setCameraUI(b.dataset.camera);}else if(b.dataset.metric){const def=definitions[b.dataset.metric];openDialog(def[0],`<p>${def[1]}</p><div class="notice">${selected()?.simulated?'Current values belong to a synthetic demo.':'An unavailable value means it was not supplied by the feed.'}</div><button class="primary" data-action="close-dialog">Got it</button>`);}});
document.addEventListener('change',ev=>{if(ev.target.dataset.layer){map[ev.target.dataset.layer]=ev.target.checked;map.draw();}});
$('#search').addEventListener('input',search);$('#search').addEventListener('keydown',ev=>{if(ev.key==='Escape')closeSearch();if(ev.key==='ArrowDown'){ev.preventDefault();$('#search-results button')?.focus();}});
$('#timeline').addEventListener('input',ev=>{state.playing=false;if(state.mode==='demo'){state.demoTime=Number(ev.target.value);state.flights=demoFlights(state.demoTime);}else state.replayTime=Number(ev.target.value);refresh();const f=selected();if(f&&scene&&state.scene)scene.update(f,true);if(f&&terrain)terrain.update(f);});
document.addEventListener('keydown',ev=>{if(['INPUT','TEXTAREA','SELECT'].includes(ev.target.tagName))return;if(ev.key==='/'&&!$('#dialog').open){ev.preventDefault();$('#search').focus();}if(ev.key===' '&&!$('#dialog').open&&ev.target.tagName!=='BUTTON'){ev.preventDefault();togglePlay();}if(ev.key==='Escape'&&!$('#dialog').open){if(state.scene)closeScene();$('.workspace').classList.remove('detail-open');}});
document.addEventListener('visibilitychange',()=>{lastFrame=performance.now();if(!document.hidden&&state.mode==='live')schedulePoll(2000);});
function animate(t){const dt=lastFrame?Math.min((t-lastFrame)/1000,.1):0;lastFrame=t;if(!document.hidden&&state.playing){if(state.mode==='demo'){state.demoTime=Math.min(DEMO_DURATION,state.demoTime+dt*state.rate);state.flights=demoFlights(state.demoTime);if(state.demoTime>=DEMO_DURATION)state.playing=false;}else if(state.replayTime!==null){const end=state.history.get(state.selected)?.at(-1)?.positionTime||state.replayTime;state.replayTime=Math.min(end,state.replayTime+dt*state.rate);if(state.replayTime>=end)state.playing=false;}}
 if(!document.hidden&&t-lastUI>300){updateMap();renderPlayback();renderClock();const f=selected();if(f){if(state.nav==='explore'&&state.tab==='overview'){for(const [key,kind] of [['altitude','alt'],['groundSpeed','speed'],['verticalRate','vertical'],['track','°']]){const el=$(`[data-value="${key}"]`);if(el)el.innerHTML=fmt(f[key],kind,kind==='vertical'&&state.units==='metric'?1:0)+`<small>${unit(kind)}</small>`;}if($('#flight-phase'))$('#flight-phase').textContent=phase(f);if($('#altitude-chart'))$('#altitude-chart').innerHTML=chart(f);}if($('#detail-data-status'))$('#detail-data-status').textContent=dataStatus(f);if($('#scene-source'))$('#scene-source').textContent=f.simulated?'SIMULATED FLIGHT':state.replayTime!==null?'SESSION REPLAY':quality(f).status.toUpperCase()+' · ADS-B';}lastUI=t;}
 const active=selected();if(active&&scene&&state.scene&&!terrain&&!document.hidden)scene.update(displayFlight(active));if(active&&terrain&&!document.hidden)terrain.update(displayFlight(active));
 requestAnimationFrame(animate);
}
refresh();renderClock();requestAnimationFrame(animate);

